#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# 티켓 26 6절: 실제 키로 예비 모델 전환 확인(docs/docker.md). 저장소 루트에서 .env를 읽고 쓴다.
cd "$(dirname "$0")/.."
CHECK_DIR=data/runs/fallback-check
SUMMARY="$CHECK_DIR/summary.md"
mkdir -p "$CHECK_DIR"
LITELLM=http://localhost:4000

# litellm만 주어진 Groq 키로 다시 만든다. 셸 환경 변수가 .env보다 앞선다.
litellm_with_key() {
  GROQ_API_KEY="$1" docker compose up -d --force-recreate --no-deps litellm
  until curl -sf "$LITELLM/health/liveliness" >/dev/null; do sleep 2; done
}

# model_group 모델이름: 그 이름으로 한 번 묻고 답한 모델 묶음(x-litellm-model-group)을 찍는다
model_group() {
  local tmp; tmp=$(mktemp)
  printf '{"model":"%s","messages":[{"role":"user","content":"Reply with OK."}],"max_tokens":200}' "$1" > "$tmp.body"
  curl -s --max-time 1000 -D "$tmp" -o /dev/null \
    -H "Authorization: Bearer $LITELLM_MASTER_KEY" -H "Content-Type: application/json" \
    --data-binary @"$tmp.body" "$LITELLM/v1/chat/completions" || true
  grep -i '^x-litellm-model-group:' "$tmp" | tr -d '\r' | awk '{print $2}' || true
  rm -f "$tmp" "$tmp.body"
}

# config.yaml에서 model_name 다음에 오는 Groq 모델 이름
groq_name() {
  awk -v want="model_name: $1" '$0 ~ want"$" {f=1} f && /model: groq\// {sub(/.*model: groq\//, ""); print; exit}' docker/litellm/config.yaml
}

# run_round 회차 기대llm 기대vlm: 답한 모델 묶음을 보고 합성 서랍장으로 파이프라인을 돌려 summary.md에 남긴다
run_round() {
  local name="$1" out="$CHECK_DIR/$1" llm vlm result formats
  step "llm에 묻는 중…"
  llm=$(model_group llm)
  if [[ "$llm" == "$2" ]]; then say "${GREEN}✓${RESET} llm → $llm"; else warn "llm → ${llm:-답 없음} (기대 $2)"; fi
  step "vlm에 묻는 중…"
  vlm=$(model_group vlm)
  if [[ "$vlm" == "$3" ]]; then say "${GREEN}✓${RESET} vlm → $vlm"; else warn "vlm → ${vlm:-답 없음} (기대 $3)"; fi

  step "합성 서랍장 녹화본으로 파이프라인을 돌린다. 몇 분 걸리고, 로컬 모델이면 더 오래 걸린다."
  # 사례 저장소는 회차마다 따로 둔다. 앞 회차의 사례가 예시로 끼지 않고, 실제 사례 저장소(data/cases)도 건드리지 않는다.
  # 컨테이너 안 경로(/app/…)는 Git Bash가 Windows 경로로 바꾸지 않게 이 명령에서만 변환을 끈다.
  # 끄는 범위를 넓히면 Windows용 curl이 mktemp의 /tmp/… 경로를 찾지 못한다.
  MSYS_NO_PATHCONV=1 docker compose run --rm -T -e CASES_DIR="/app/$out/cases" pipeline scripts/run-pipeline.ts \
    /app/fixtures/synthetic/drawer.json "/app/$CHECK_DIR/intake.json" "/app/$CHECK_DIR/rules.json" "/app/$out" \
    2>&1 | tee "$out.out" || true
  # 끝까지 돌면 마지막 줄이 실행 결과({"status":…})이고, 파이프라인 밖 오류로 끊기면 그 오류 줄을 남긴다
  result=$(grep -E '^\{"status"' "$out.out" | tail -n1 || true)
  [[ -n "$result" ]] || result="끊김: $(grep -m1 -E '^Error' "$out.out" | cut -c1-300 || true)"
  formats=$(node -e '
    const log = JSON.parse(require("fs").readFileSync(process.argv[1], "utf8"));
    const count = {};
    for (const e of log) if (e.detail && e.detail.schemaErrors) count[e.stage] = (count[e.stage] || 0) + 1;
    console.log(Object.entries(count).map(([stage, n]) => `${stage} ${n}번`).join(", ") || "없음");
  ' "$out/log.json" 2>/dev/null || echo "log.json 없음")
  say ""
  say "파이프라인 결과: $result"
  say "형식 검사에 걸려 다시 물은 횟수: $formats"
  {
    printf '## %s (%s)\n\n' "$name" "$(date '+%Y-%m-%d %H:%M')"
    printf -- '- llm: %s (기대 %s)\n' "${llm:-답 없음}" "$2"
    printf -- '- vlm: %s (기대 %s)\n' "${vlm:-답 없음}" "$3"
    printf -- '- 파이프라인 결과: `%s`\n' "$result"
    printf -- '- 형식 검사에 걸려 다시 물은 횟수: %s\n' "$formats"
    printf -- '- 처리 기록: `%s/log.json`\n\n' "$out"
  } >> "$SUMMARY"
  note "결과를 $SUMMARY 에 덧붙였다. 형식 오류가 다음 단계로 샜는지는 $out/log.json 에서 볼 수 있다."
  pause "다음으로 넘어가려면 Enter"
}

run_wizard() {

TOTAL_STAGES=8

banner "티켓 26 6절: 실제 키로 예비 모델 전환 확인"

stage "LiteLLM 프록시 키"
say "파이프라인과 LiteLLM이 함께 쓰는 프록시 키다. 사람이 고를 값이 아니라 이미 있으면 그대로 두고, 없으면 새로 만든다."
LITELLM_MASTER_KEY=$(_existing LITELLM_MASTER_KEY || true)
if [[ -z "$LITELLM_MASTER_KEY" ]]; then
  LITELLM_MASTER_KEY=$(node -e 'console.log("sk-" + require("crypto").randomBytes(24).toString("hex"))')
  note "새 키를 만들었다."
else
  note ".env에 있는 키를 그대로 쓴다."
fi
write_env LITELLM_MASTER_KEY "$LITELLM_MASTER_KEY"
pause "Enter"

stage "Groq API 키"
open_url "https://console.groq.com/keys"
step "Create API Key를 눌러 키를 만들고 복사한다."
ask_secret GROQ_API_KEY "Groq API 키 붙여 넣기:"
write_env GROQ_API_KEY "$GROQ_API_KEY"
pause "Enter"

stage "Groq 모델 이름 확인"
say "Groq가 내놓은 모델 목록에 config.yaml의 이름이 있는지 본다."
GROQ_MODELS=$(curl -s -H "Authorization: Bearer $GROQ_API_KEY" https://api.groq.com/openai/v1/models \
  | node -e 'let s = ""; process.stdin.on("data", (d) => (s += d)).on("end", () => { try { console.log(JSON.parse(s).data.map((m) => m.id).join("\n")); } catch { console.log(""); } })')
if [[ -z "$GROQ_MODELS" ]]; then
  warn "모델 목록을 받지 못했다. 키가 틀렸을 수 있다. 다시 돌려 2단계에서 키를 고친다."
  SKIPPED+=("Groq 모델 이름 확인(모델 목록을 받지 못함)")
else
  note "Groq 모델:"
  while read -r m; do note "  $m"; done <<< "$GROQ_MODELS"
  for group in llm vlm; do
    current=$(groq_name "$group")
    if grep -qxF "$current" <<< "$GROQ_MODELS"; then
      say "${GREEN}✓${RESET} $group 이름 $current 이 목록에 있다."
    else
      warn "$group 이름 $current 이 목록에 없다."
      ask NEW_NAME "위 목록에서 $group 에 쓸 모델 이름:"
      if [[ -n "$NEW_NAME" ]] && confirm "docker/litellm/config.yaml의 groq/$current 를 groq/$NEW_NAME 으로 고칠까?"; then
        sed -i "s#model: groq/$current\$#model: groq/$NEW_NAME#" docker/litellm/config.yaml
        say "${GREEN}✓${RESET} 고쳤다. 커밋은 확인이 끝난 뒤 Claude에게 맡긴다."
        printf -- '- config.yaml의 %s 이름을 groq/%s 에서 groq/%s 로 고쳤다\n\n' "$group" "$current" "$NEW_NAME" >> "$SUMMARY.pending"
      else
        SKIPPED+=("config.yaml의 $group Groq 모델 이름 고치기")
      fi
    fi
  done
fi
pause "Enter"

stage "Docker 구성 띄우기"
if ! docker info >/dev/null 2>&1; then
  say "Docker Desktop이 꺼져 있어 켠다. 처음 켜면 1~2분 걸린다."
  if command -v cygpath >/dev/null 2>&1 && [[ -n "${LOCALAPPDATA:-}" ]]; then
    "$(cygpath "$LOCALAPPDATA")/Programs/DockerDesktop/Docker Desktop.exe" >/dev/null 2>&1 &
  else
    step "Docker Desktop을 직접 켠다."
  fi
  until docker info >/dev/null 2>&1; do sleep 3; done
fi
say "${GREEN}✓${RESET} Docker가 떴다."
docker compose up -d --build
docker compose build pipeline
step "임베딩 모델(embeddinggemma)을 받는다. 사례 저장소가 늘 쓰므로 꼭 필요하다."
docker compose exec ollama ollama pull embeddinggemma
mkdir -p "$CHECK_DIR"
# 티켓 15 수동 확인과 같은 정보 입력과 치수 규칙
printf '%s\n' '{"name":"1단 서랍장","kind":"서랍장","memo":"슬라이더는 전체 폭 하나만. 폭 400~800","thickness":"hide"}' > "$CHECK_DIR/intake.json"
printf '%s\n' '[{"id":"치수규칙/서랍장/폭","kind":"서랍장","part":"폭","axis":"W","min":300,"max":1200,"origin":"티켓 15 수동 확인"},{"id":"치수규칙/서랍장/깊이","kind":"서랍장","part":"깊이","axis":"D","min":250,"max":700,"origin":"티켓 15 수동 확인"},{"id":"치수규칙/서랍장/높이","kind":"서랍장","part":"높이","axis":"H","min":300,"max":1200,"origin":"티켓 15 수동 확인"}]' > "$CHECK_DIR/rules.json"
printf '# 예비 모델 전환 확인 (티켓 26 6절)\n\n- 커밋: `%s`\n\n' "$(git log -1 --format='%h %s')" > "$SUMMARY"
if [[ -f "$SUMMARY.pending" ]]; then cat "$SUMMARY.pending" >> "$SUMMARY"; rm -f "$SUMMARY.pending"; fi
note "정보 입력과 치수 규칙을 $CHECK_DIR 에 썼다."
pause "Enter"

stage "로컬 모델 받기"
say "마지막 예비인 로컬 모델 gpt-oss:20b(약 13GB)와 qwen3-vl:4b(약 3.3GB)를 받는다."
if confirm "약 16GB를 받을까?"; then
  docker compose exec ollama ollama pull gpt-oss:20b
  docker compose exec ollama ollama pull qwen3-vl:4b
  say "${GREEN}✓${RESET} 받았다."
else
  warn "받지 않았다. 7단계(로컬 모델 회차)는 실패한다."
  SKIPPED+=("로컬 모델 받기: docker compose exec ollama ollama pull gpt-oss:20b / qwen3-vl:4b")
fi
pause "Enter"

stage "1회차: Groq가 답한다"
say "Groq 키를 넣은 채로 llm·vlm이 Groq에서 답하는지 본다."
litellm_with_key "$GROQ_API_KEY"
run_round 1-groq llm vlm

stage "2회차: Groq 키를 비우면 로컬 모델이 답한다"
say ".env는 그대로 두고 litellm만 Groq 키 없이 다시 띄운다. 로컬 모델은 CPU에서 느려 한 번 묻는 데 몇 분이 걸릴 수 있다."
litellm_with_key ""
run_round 2-local llm-local vlm-local

stage "원래대로 돌리기"
docker compose up -d --force-recreate --no-deps litellm
until curl -sf "$LITELLM/health/liveliness" >/dev/null; do sleep 2; done
say "${GREEN}✓${RESET} litellm이 .env의 키로 다시 떴다."
say "확인 결과는 $SUMMARY 에 있다. Claude에게 이 파일을 티켓 26에 기록해 달라고 한다."
pause "Enter"

finish
}

run_wizard "$@"; exit
